  '  if(!input){setSyncCode("");window.alert("\\u5df2\\u95dc\\u9589\\u540c\\u6b65");return;}',
  '  setSyncCode(input);',
  '  cloudPull(function(ok){',
  '    initHome();',
  '    window.alert(ok?("\\u540c\\u6b65\\u78bc\\u5df2\\u8a2d\\u5b9a\\uff0c\\u53e6\\u4e00\\u53f0\\u88dd\\u7f6e\\u8acb\\u8f38\\u5165\\u540c\\u6a23\\u7684\\u78bc\\uff1a"+input):"\\u540c\\u6b65\\u5931\\u6557\\uff0c\\u8acb\\u6aa2\\u67e5\\u7db2\\u8def\\u5f8c\\u518d\\u8a66");',
  '  });',
  '}',
  'function tx(id,t){var e=document.getElementById(id);if(e)e.textContent=t;}',
  'function mkEl(tag,cls,txt){var e=document.createElement(tag);if(cls)e.className=cls;if(txt!==undefined)e.textContent=txt;return e;}',
  'function showScreen(id){',
  '  var all=document.querySelectorAll(".scr"),i;',
  '  for(i=0;i<all.length;i++)all[i].classList.remove("active");',
  '  var el=document.getElementById(id);if(el)el.classList.add("active");',
  '  var nav=document.getElementById("bnav");',
  '  nav.style.display=(id==="ss"||id==="so"||id==="sci"||id==="sidq")?"none":"flex";',
  '  var btns=document.querySelectorAll(".nb"),j;',
  '  for(j=0;j<btns.length;j++)btns[j].classList.remove("active");',
  '  if(id==="sh"){var nh=document.getElementById("nb-h");if(nh)nh.classList.add("active");}',
  '  if(id==="shist"){var nhi=document.getElementById("nb-hi");if(nhi)nhi.classList.add("active");}',
  '}',
  'var OBI=0;',
  'function initOnboard(){',
  '  var ob=S.ob,oe=S.ob_emoji,i;',
  '  for(i=0;i<3;i++){tx("oe"+i,oe[i]);tx("ot"+i,ob[i].title);tx("od"+i,ob[i].desc);}',
  '  tx("sk-btn",S.ob_skip);tx("ob-btn",S.ob_next);obGo(0);',
  '}',
  'function obGo(idx){',
  '  OBI=idx;',
  '  var slides=document.querySelectorAll(".ob-slide"),i;',
  '  for(i=0;i<slides.length;i++)slides[i].classList.remove("active");',
  '  var dots=document.querySelectorAll(".dot");',
  '  for(i=0;i<dots.length;i++)dots[i].classList.remove("active");',
  '  var s=document.getElementById("ob"+idx);if(s)s.classList.add("active");',
  '  var d=document.getElementById("d"+idx);if(d)d.classList.add("active");',
  '  tx("ob-btn",idx<2?S.ob_next:S.ob_start);',
  '}',
  'function obNext(){if(OBI<2){obGo(OBI+1);}else{var data=ld();data.ft=false;sd(data);initHome();showIdentityQuiz();}}',
  'function skipOb(){var data=ld();data.ft=false;sd(data);initHome();showScreen("sh");}',
  'function fmtDate(d){return(d.getMonth()+1)+"/"+d.getDate()+" ("+S.wk[d.getDay()]+")";}',
  'function fmtTime(d){return d.getHours()+":"+(d.getMinutes()<10?"0":"")+d.getMinutes();}',
  'function initHome(){',
  '  var h=new Date().getHours();',
  '  tx("hg",h<12?S.greet_am:h<17?S.greet_pm:S.greet_ev);',
  '  tx("hd",fmtDate(new Date()));',
  '  tx("hct",S.home_card_title);tx("hcs",S.home_card_sub);tx("hcb",S.home_card_btn);',
  '  var ft=document.getElementById("hfive");ft.innerHTML="";',
  '  S.home_five.forEach(function(t,i){',
