  '    (function(idx){tag.onclick=function(){showDimInfo(idx);};})(i);',
  '    ft.appendChild(tag);',
  '  });',
  '  tx("htip",S.home_tip);var _di=["\ud83c\udf7d\ufe0f","\ud83c\udfc3","\ud83d\ude34","\ud83d\udca2","\ud83d\udc65"];var _dd=["\u5403","\u52d5","\u7761","\u58d3","\u4eba"];var _ds=["\u98f2\u98df\u578b\u614b","\u904b\u52d5\u98f2\u98df","\u7761\u7720\u98f2\u98df","\u58d3\u529b\u7ba1\u7406","\u4eba\u969b\u60c5\u5883"];for(var _i=0;_i<5;_i++){tx("dgi"+_i,_di[_i]);tx("dgd"+_i,_dd[_i]);tx("dgs"+_i,_ds[_i]);}var _keys=["eat","move","sleep","stress","social"];_keys.forEach(function(k,i){var el=document.getElementById("dgc"+i);if(!el)return;if(k==="move"){el.onclick=showMove;}else{(function(key){el.onclick=function(){showDimScreen(key);};})(k);}});renderIdentityCard();renderToday();',
  '}',
  'function renderToday(){',
  '  var data=ld();var area=document.getElementById("today-area");area.innerHTML="";',
  '  if(!data.ins||data.ins.length===0)return;',
  '  var today=new Date();',
  '  var recent=data.ins.filter(function(x){var d=new Date(x.ts);return d.getDate()===today.getDate()&&d.getMonth()===today.getMonth();});',
  '  if(recent.length===0)return;',
  '  area.appendChild(mkEl("div","today-lbl",S.home_rec_lbl));',
  '  recent.slice(0,2).forEach(function(item){',
  '    var row=mkEl("div","today-item");',
  '    (function(it){row.onclick=function(){showHistoryDetail(it);};})(item);',
  '    var behd=S.beh[item.beh];',
  '    row.appendChild(mkEl("div","today-em",behd?behd.icon:"?"));',
  '    var info=mkEl("div","today-info");',
  '    info.appendChild(mkEl("div","today-beh",behd?behd.title:""));',
  '    info.appendChild(mkEl("div","today-cr",S.crave_names[item.crave]||""));',
  '    row.appendChild(info);',
  '    row.appendChild(mkEl("div","today-time",fmtTime(new Date(item.ts))));',
  '    area.appendChild(row);',
  '  });',
  '}',
  'function startCheckin(){',
  '  CS={};QI=0;',
  '  document.getElementById("chat-msgs").innerHTML="";',
  '  document.getElementById("qr-area").innerHTML="";',
  '  tx("cin",S.app_name);tx("cisub",S.ci_header_sub);',
  '  showScreen("sci");',
  '  addBot(S.ci_greeting,400);',
  '  setTimeout(nextQ,1400);',
  '}',
  'function nextQ(){',
  '  var key=QK[QI];',
  '  addBot(S["q_"+key],300);',
  '  setTimeout(function(){showQR(S["q_"+key+"_opts"]);},1000);',
  '}',
  'function addBot(text,delay){',
  '  setTimeout(function(){',
  '    var msgs=document.getElementById("chat-msgs");',
  '    var d=mkEl("div","msg bot-msg");',
  '    d.appendChild(mkEl("div","bubble",text));',
  '    msgs.appendChild(d);msgs.scrollTop=msgs.scrollHeight;',
  '  },delay||0);',
