  'function showQR(opts){',
  '  var area=document.getElementById("qr-area");area.innerHTML="";',
  '  opts.forEach(function(opt){',
  '    var btn=mkEl("button","qr-btn",opt.l);',
  '    (function(v,l){btn.onclick=function(){handleAns(v,l);};})(String(opt.v),opt.l);',
  '    area.appendChild(btn);',
  '  });',
  '}',
  'function advanceQ(){',
  '  QI++;',
  '  if(QI<QK.length){setTimeout(nextQ,600);return;}',
  '  addBot(S.ci_done,600);',
  '  var idData=ld().identity;var idT=idData?idTypeByKey(idData.key):null;',
  '  if(idT){addBot(idT.cheer,1700);setTimeout(buildResult,3300);}',
  '  else{setTimeout(buildResult,2200);}',
