  'function ackAndAdvance(ack){if(ack){addBot(ack,400);setTimeout(advanceQ,1400);}else{advanceQ();}}',
  'function getAckMsg(key,val){',
  '  if(key==="energy"&&val<=2)return S.ack_msgs.energy_low;',
  '  if(key==="sleep"&&val<=2)return S.ack_msgs.sleep_bad;',
  '  if(key==="social"&&val<=2)return S.ack_msgs.social_bad;',
  '  if(key==="move"&&val>=3)return S.ack_msgs.move_good;',
  '  return null;',
  '}',
  'function handleAns(val,label){',
  '  if(STRESS_FOLLOWUP){',
  '    STRESS_FOLLOWUP=false;CS.stress_peak=(val==="beyond");',
  '    addUser(label);document.getElementById("qr-area").innerHTML="";',
  '    if(val==="beyond"){addBot(S.ack_msgs.stress_beyond,400);setTimeout(advanceQ,1400);}else{advanceQ();}',
  '    return;',
  '  }',
  '  var key=QK[QI];',
  '  if(key==="stress"){',
  '    var raw=parseInt(val,10);',
  '    CS.stress=raw>=8?1:raw>=6?2:raw>=3?3:4;CS.stress_raw=raw;',
  '    addUser(label);document.getElementById("qr-area").innerHTML="";',
  '    if(raw>=10){',
  '      STRESS_FOLLOWUP=true;',
  '      addBot(S.stress_followup_q,600);',
  '      setTimeout(function(){showQR([{v:"peak",l:S.stress_followup_a1},{v:"beyond",l:S.stress_followup_a2}]);},1400);',
  '    }else{ackAndAdvance(raw>=8?S.ack_msgs.stress_high:null);}',
  '    return;',
  '  }',
  '  var intVal=(key==="crave")?0:parseInt(val,10);',
  '  CS[key]=(key==="crave")?val:intVal;',
  '  addUser(label);document.getElementById("qr-area").innerHTML="";',
  '  ackAndAdvance(getAckMsg(key,intVal));',
  '}',
  'function analyze(s){',
  '  if(s.sleep<=2&&s.crave==="sweet")return"sleep_sugar";',
  '  var stressCraves=["fried","sweet","bbq","fastfood"];',
  '  if(s.stress<=2&&stressCraves.indexOf(s.crave)>=0)return"stress_eating";',
  '  if(s.social<=3&&(s.crave==="fried"||s.crave==="sweet"||s.crave==="bbq"))return"emotion_eating";',
  '  if(s.energy<=2&&s.crave==="soup")return"comfort_soup";',
  '  if(s.move>=3)return"active_replenish";',
  '  if(s.energy<=2)return"low_energy";',
  '  return"normal";',
  '}',
